function survivesTwoFlips(num: number): boolean {
  const flip = (x: number): number => {
    let out = 0;
    while (x > 0) {
      out = out * 10 + (x % 10);
      x = Math.floor(x / 10);
    }
    return out;
  };
  return flip(flip(num)) === num;
}

